const tabId = 2126149105;

const flights = await browserjs(tabId, () => {
  const items = [];
  // Find all flight elements or cards in Google Flights
  // Google flights list items usually have role="listitem" or aria-label
  const listItems = Array.from(document.querySelectorAll('ul.Rk10dc > li, li.pIav2d'));

  listItems.forEach(li => {
    const text = li.innerText;
    // Extract times
    const timeMatch = text.match(/(\d{1,2}:\d{2}\s*[AP]M)\s*–\s*(\d{1,2}:\d{2}\s*[AP]M)/);
    // Extract airline
    const airlines = ['American', 'Delta', 'United', 'Southwest', 'JetBlue', 'Frontier', 'Spirit', 'Breeze'];
    let airline = 'Unknown';
    for (const a of airlines) {
      if (text.includes(a)) {
        airline = a;
        break;
      }
    }
    // Extract duration
    const durMatch = text.match(/(\d+\s*hr(?:\s*\d+\s*min)?)/);
    // Stops
    const isNonstop = text.includes('Nonstop');
    const stopMatch = text.match(/(\d+)\s*stop/);
    const stops = isNonstop ? 'Nonstop' : (stopMatch ? `${stopMatch[1]} stop` : 'Unknown');
    // Price
    const priceMatch = text.match(/\$(\d[\d,]*)/);
    const price = priceMatch ? parseInt(priceMatch[1].replace(/,/g, '')) : null;

    if (timeMatch && price) {
      items.push({
        airline,
        departure: timeMatch[1],
        arrival: timeMatch[2],
        duration: durMatch ? durMatch[1] : '',
        stops,
        priceTotal: price,
        pricePerPerson: (price / 3).toFixed(2),
        raw: text.split('\n').filter(t => t.trim().length > 0)
      });
    }
  });
  return items;
});

