const results = JSON.parse(resText);

for (const [key, flights] of Object.entries(results)) {
  console.log(`=== ${key} (${flights.length} flights) ===`);
  // Group by airline
  const byAirline = {};
  flights.forEach(f => {
    if (!byAirline[f.airline]) byAirline[f.airline] = [];
    byAirline[f.airline].push(f);
  });

  for (const [airline, list] of Object.entries(byAirline)) {
    // Sort by price
    list.sort((a,b) => a.priceTotal - b.priceTotal);
    const nonstops = list.filter(f => f.stops === 'Nonstop');
    const cheapest = list[0];
    const cheapestNonstop = nonstops[0] || null;
    console.log(`  ${airline}:`);
    console.log(`    Cheapest overall: $${cheapest.priceTotal} total ($${cheapest.pricePerPax}/pax), ${cheapest.stops}, ${cheapest.dep}-${cheapest.arr} (${cheapest.dur})`);
    if (cheapestNonstop && cheapestNonstop !== cheapest) {
      console.log(`    Cheapest nonstop: $${cheapestNonstop.priceTotal} total ($${cheapestNonstop.pricePerPax}/pax), ${cheapestNonstop.dep}-${cheapestNonstop.arr} (${cheapestNonstop.dur})`);
    }
  }
}

