const tabId = 2126149105;

const combinations = [
  { orig: "DCA", date: "2027-01-29" },
  { orig: "DCA", date: "2027-01-30" },
  { orig: "DCA", date: "2027-01-31" },
  { orig: "IAD", date: "2027-01-29" },
  { orig: "IAD", date: "2027-01-30" },
  { orig: "IAD", date: "2027-01-31" },
  { orig: "BWI", date: "2027-01-29" },
  { orig: "BWI", date: "2027-01-30" },
  { orig: "BWI", date: "2027-01-31" }
];

const allResults = {};

for (const combo of combinations) {
  const key = `${combo.orig}_${combo.date}`;
  console.log(`Searching for ${key}...`);
  const url = `https://www.google.com/travel/flights?q=Flights%20to%20MCO%20from%20${combo.orig}%20on%20${combo.date}%20one%20way%203%20adults`;

  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 15000 });
  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 4000 });

  const extracted = await browserjs(tabId, () => {
    const listItems = Array.from(document.querySelectorAll('ul.Rk10dc > li, li.pIav2d'));
    const items = [];
    listItems.forEach(li => {
      const text = li.innerText;
      const timeMatch = text.match(/(\d{1,2}:\d{2}\s*[AP]M)\s*–\s*(\d{1,2}:\d{2}\s*[AP]M)/);
      const airlines = ['American', 'Delta', 'United', 'Southwest', 'JetBlue', 'Frontier', 'Spirit', 'Breeze', 'Sun Country', 'Allegiant', 'Avelo'];
      let matchedAirlines = [];
      for (const a of airlines) {
        if (text.includes(a)) {
          matchedAirlines.push(a);
        }
      }
      const airline = matchedAirlines.length > 0 ? matchedAirlines.join('/') : 'Other';
      const durMatch = text.match(/(\d+\s*hr(?:\s*\d+\s*min)?)/);
      const isNonstop = text.includes('Nonstop');
      const stopMatch = text.match(/(\d+)\s*stop[^\n]*/);
