      summary[combo][f.airline] = [];
    }
    summary[combo][f.airline].push({
      dep: f.dep,
      arr: f.arr,
      dur: f.dur,
      stops: f.stops,
      priceTotal: f.priceTotal,
      pricePerPax: f.pricePerPax,
      raw: f.raw
    });
  });
}

// Let's print out all details for DCA, IAD, BWI across all 3 dates
for (const combo of Object.keys(summary)) {
  console.log(`\n================== ${combo} ==================`);
  for (const [airline, list] of Object.entries(summary[combo])) {
    console.log(`-- ${airline} (${list.length} flights) --`);
