const flightData = JSON.parse((await read("tmp://flight_results.json")).text);

// Let's create a full detailed summary object for each of the 9 combinations
const detailedCombinations = [];

const combos = [
  { orig: "DCA", date: "2027-01-29", day: "Friday, Jan 29" },
  { orig: "DCA", date: "2027-01-30", day: "Saturday, Jan 30" },
  { orig: "DCA", date: "2027-01-31", day: "Sunday, Jan 31" },
  { orig: "IAD", date: "2027-01-29", day: "Friday, Jan 29" },
  { orig: "IAD", date: "2027-01-30", day: "Saturday, Jan 30" },
  { orig: "IAD", date: "2027-01-31", day: "Sunday, Jan 31" },
  { orig: "BWI", date: "2027-01-29", day: "Friday, Jan 29" },
  { orig: "BWI", date: "2027-01-30", day: "Saturday, Jan 30" },
  { orig: "BWI", date: "2027-01-31", day: "Sunday, Jan 31" }
];

for (const c of combos) {
  const key = `${c.orig}_${c.date}`;
  const flights = flightData[key] || [];

  // Group by airline
  const byAirline = {};
  flights.forEach(f => {
    if (!byAirline[f.airline]) byAirline[f.airline] = [];
    byAirline[f.airline].push(f);
  });

  detailedCombinations.push({
    ...c,
    key,
    airlines: byAirline
  });
}

// Write to scratchpad file for verification
await write("tmp://final_matrix_data.json", JSON.stringify(detailedCombinations, null, 2), "application/json");
console.log("Saved final matrix data to tmp://final_matrix_data.json");

